import {spawnSync} from 'node:child_process'
function naive(tasks, edges, W){
  const names=Object.keys(tasks).sort()
  const deps={};names.forEach(n=>deps[n]=new Set());for(const [a,b] of edges)deps[a].add(b)
  const pr={};const P=n=>pr[n]??=tasks[n]+Math.max(0,...names.filter(m=>deps[m].has(n)).map(P))
  names.forEach(P)
  const fin={},run=Array.from({length:W},()=>[]),free=Array(W).fill(0);let t=0;const st=new Set()
  while(st.size<names.length){
    for(;;){
      const w=free.findIndex(f=>f<=t); if(w<0)break
      const rd=names.filter(n=>!st.has(n)&&[...deps[n]].every(d=>fin[d]!==undefined&&fin[d]<=t)).sort((a,b)=>pr[b]-pr[a]||(a<b?-1:1))
      if(!rd.length)break
      const n=rd[0];st.add(n);fin[n]=t+tasks[n];free[w]=fin[n];run[w].push(`${n}@${t}-${fin[n]}`)
    }
    const nx=free.filter(f=>f>t); if(!nx.length)break; t=Math.min(...nx)
  }
  return run.map((r,i)=>`worker ${i}:${r.map(x=>' '+x).join('')}\n`).join('')+`makespan ${Math.max(0,...Object.values(fin))}\n`
}
for(let it=0;it<400;it++){
  const n=1+Math.floor(Math.random()*8);const tasks={};const nm=[...Array(n)].map((_,i)=>'t'+i)
  nm.forEach(x=>tasks[x]=Math.floor(Math.random()*4))
  const edges=[];for(let i=0;i<n;i++)for(let j=0;j<i;j++)if(Math.random()<.3)edges.push([nm[i],nm[j]])
  const W=1+Math.floor(Math.random()*3)
  let inp=nm.map(x=>`task ${x} ${tasks[x]}`).join('\n')+'\n'+edges.map(e=>`dep ${e[0]} ${e[1]}`).join('\n')+'\n'
  const r=spawnSync('node',['src/cli.js','pack',String(W)],{input:inp,encoding:'utf8'})
  const e=naive(tasks,edges,W)
  if(r.stdout!==e){console.log(inp,W,r.stdout,e);process.exit(1)}
}
console.log('ok')
